-- ALTER//CASE initial commerce schema. Apply with: supabase db push
create type public.user_role as enum ('customer','admin','brand');
create table public.profiles (id uuid primary key references auth.users on delete cascade, full_name text, email text, phone text, avatar_url text, role public.user_role not null default 'customer', created_at timestamptz not null default now());
create table public.brands (id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique);
create table public.phone_models (id uuid primary key default gen_random_uuid(),brand_id uuid not null references public.brands on delete cascade,name text not null,slug text not null unique);
create table public.collections (id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text,image_url text,launch_date timestamptz,active boolean default true);
create table public.products (id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text,price integer not null check(price>=0),compare_price integer,category text not null,collection_id uuid references public.collections,featured boolean default false,limited boolean default false,active boolean default true,created_at timestamptz not null default now());
create table public.product_variants (id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products on delete cascade,phone_model_id uuid not null references public.phone_models,color text not null,sku text not null unique,stock integer not null default 0 check(stock>=0),price integer);
create table public.product_images (id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products on delete cascade,variant_id uuid references public.product_variants on delete cascade,image_url text not null,position smallint not null default 0);
create table public.favorites (user_id uuid not null references public.profiles on delete cascade,product_id uuid not null references public.products on delete cascade,created_at timestamptz default now(),primary key(user_id,product_id));
create table public.custom_designs (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,phone_model_id uuid references public.phone_models,image_url text,text_content text,font text,color text,created_at timestamptz default now());
create table public.orders (id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles,order_number text not null unique,status text not null default 'pending',subtotal integer not null,shipping_address jsonb not null default '{}'::jsonb,created_at timestamptz default now());
create table public.order_items (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders on delete cascade,variant_id uuid references public.product_variants,product_name text not null,quantity integer not null check(quantity>0),unit_price integer not null);
create table public.cart_items (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,variant_id uuid not null references public.product_variants on delete cascade,quantity integer not null check(quantity>0),unique(user_id,variant_id));
create table public.reviews (id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles on delete set null,product_id uuid not null references public.products on delete cascade,rating int not null check(rating between 1 and 5),body text,created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.brands enable row level security; alter table public.phone_models enable row level security; alter table public.collections enable row level security; alter table public.products enable row level security; alter table public.product_variants enable row level security; alter table public.product_images enable row level security; alter table public.favorites enable row level security; alter table public.custom_designs enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.cart_items enable row level security; alter table public.reviews enable row level security;
create function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$select exists(select 1 from public.profiles where id=(select auth.uid()) and role='admin')$$; revoke all on function public.is_admin() from public; grant execute on function public.is_admin() to authenticated;
create policy "catalog public read" on public.products for select using(active=true or public.is_admin()); create policy "variants public read" on public.product_variants for select using(true); create policy "images public read" on public.product_images for select using(true); create policy "brands public read" on public.brands for select using(true); create policy "models public read" on public.phone_models for select using(true); create policy "collections public read" on public.collections for select using(active=true or public.is_admin());
create policy "profile own" on public.profiles for all to authenticated using((select auth.uid())=id) with check((select auth.uid())=id); create policy "favorite own" on public.favorites for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id); create policy "cart own" on public.cart_items for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id); create policy "design own" on public.custom_designs for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id); create policy "orders own" on public.orders for select to authenticated using((select auth.uid())=user_id); create policy "order items own" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=(select auth.uid())));
create policy "admin manage products" on public.products for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "admin manage variants" on public.product_variants for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "admin manage collections" on public.collections for all to authenticated using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public) values ('product-images','product-images',true),('custom-designs','custom-designs',false) on conflict do nothing;
create policy "public product images" on storage.objects for select using(bucket_id='product-images'); create policy "user custom upload" on storage.objects for insert to authenticated with check(bucket_id='custom-designs' and (storage.foldername(name))[1]=(select auth.uid()::text)); create policy "user own custom read" on storage.objects for select to authenticated using(bucket_id='custom-designs' and (storage.foldername(name))[1]=(select auth.uid()::text));
